    // Original C:
    //   mean[j] = 0;
    //   for (i = 0; i < N; i++)
    //       mean[j] += data[i][j];
    //   mean[j] /= float_n;
    //
    // We implement: mean[j] = sum_i data[i][j] / float_n.
    Func mean("mean");
    {
        RDom r_mean(0, n, "r_mean");
        Expr zero = cast<num_t>(Expr(0.0));

        mean(j) = zero;
        // Incremental average: sum of data / float_n
        mean(j) += data_param(j, r_mean) / float_n_param;
    }

    // Column-wise variance (without dividing by float_n yet):
    //   var[j] = sum_i (data[i][j] - mean[j])^2
    Func var("var");
    {
        RDom r_var(0, n, "r_var");
        Expr zero = cast<num_t>(Expr(0.0));

        var(j) = zero;
        Expr diff = data_param(j, r_var) - mean(j);
        var(j) += diff * diff;
    }

    // Standard deviation with epsilon handling:
    // Original C:
    //   stddev[j] = 0;
    //   for (i) stddev[j] += (data[i][j] - mean[j])^2;
    //   stddev[j] /= float_n;
    //   stddev[j] = sqrt(stddev[j]);
    //   stddev[j] = stddev[j] <= eps ? 1.0 : stddev[j];
    //
    // We compute:
    //   sigma = sqrt(var[j] / float_n);
    //   stddev[j] = (sigma <= eps) ? 1.0 : sigma;
    Func stddev("stddev");
    {
        Expr eps    = cast<num_t>(Expr(0.1));  // SCALAR_VAL(0.1)
        Expr one    = cast<num_t>(Expr(1.0));
        Expr sigma  = sqrt(var(j) / float_n_param);
        stddev(j)   = select(sigma <= eps, one, sigma);
    }

    // Center and reduce the column vectors:
    // Original C:
    //   for (i = 0; i < N; i++)
    //     for (j = 0; j < M; j++) {
    //       data[i][j] -= mean[j];
    //       data[i][j] /= sqrt(float_n) * stddev[j];
    //     }
    //
    // We'll compute a new Func `normalized(j, i)` instead of modifying data in place:
    //   normalized(j, i) = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
    Func normalized("normalized");
    {
        Expr sqrt_n = sqrt(float_n_param);
        Expr denom  = sqrt_n * stddev(j);
        normalized(j, i) = (data_param(j, i) - mean(j)) / denom;
    }

    // Correlation matrix:
    // Original C:
    //   for (i = 0; i < M-1; i++) {
    //     corr[i][i] = 1.0;
    //     for (j = i+1; j < M; j++) {
    //       corr[i][j] = 0.0;
    //       for (k = 0; k < N; k++)
    //         corr[i][j] += data[k][i] * data[k][j];
    //       corr[j][i] = corr[i][j];
    //     }
    //   }
    //   corr[M-1][M-1] = 1.0;
    //
    // Using normalized data, the off-diagonals are dot products of
    // normalized columns. We compute the full symmetric matrix and then
    // explicitly set the diagonal to 1.0 via a guarded update.
    //
    // We implement a single reduction Func `corr(q,p)` so we can schedule it
    // efficiently (parallel + vectorized), and mask out the diagonal in the
    // reduction so corr[p,p] stays exactly 1.0.
    Func corr("corr");
    RDom r_k(0, n, "r_k");
    {
        Expr zero = cast<num_t>(Expr(0.0));
        Expr one  = cast<num_t>(Expr(1.0));

        // Initialize: diagonal = 1, off-diagonal = 0.
        corr(q, p) = select(p == q, one, zero);

        // For off-diagonal entries, accumulate the dot product of normalized
        // columns; for diagonal entries, add zero so the value stays at 1.
        Expr prod = normalized(q, r_k) * normalized(p, r_k);
        corr(q, p) += select(p == q,
                             cast<num_t>(Expr(0.0)),
                             prod);
    }

    // -------------------- Scheduling --------------------
    //
    // We focus optimization effort on:
    //   * normalized(j,i): N x M pre-normalization (streaming, cache-friendly)
    //   * corr(q,p):       M x M correlation (dominant O(N*M^2) work)
    //
    // The small 1D stages mean/var/stddev are left with a simple
    // compute_root schedule; their cost is negligible compared to corr.

    // Precompute normalization per (column, row).
    //  - parallelize across rows i (good outer parallelism)
    //  - vectorize across columns j (contiguous in memory)
    normalized
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // corr(q,p): q is the fast-varying dimension (x), p is y.
    //  - parallelize across rows p to exploit many cores
    //  - vectorize across q to exploit SIMD on contiguous data
    corr
        .compute_root()
        .parallel(p)
        .vectorize(q, vec_width);

    // Reorder the reduction update so that:
    //   outer: p (possibly running in parallel)
    //   mid:   r_k over samples
    //   inner: q, which we vectorize
    {
        RVar r_k_var = r_k.x;
        corr.update()
            .reorder(q, r_k_var, p);
        // `corr.vectorize(q, vec_width)` above applies to both the pure
        // definition and this update; here we only need to control loop order.
    }

    // (mean, var, stddev): small 1D reductions over columns; a simple
    // compute_root is sufficient; they will run before normalized/corr.
    mean.compute_root();
    var.compute_root();
    stddev.compute_root();

    // Bind parameters and input buffer.
    data_param.set(data);
    float_n_param.set(float_n);

    // Build a pipeline for the final correlation Func.
    Pipeline pipeline(corr);

    // JIT compile the pipeline.
    pipeline.compile_jit(target);

    // -------------------- Timed kernel execution --------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize corr into corr_buf.
    pipeline.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, similar to gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr_buf(jj, ii) corresponds to corr[ii][jj] in C.
                std::cerr << corr_buf(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
