    //   for (i = 0; i < N; i++)
    //       mean[j] += data[i][j];
    //   mean[j] /= float_n;
    //
    // We implement: mean[j] = sum_i data[i][j] / float_n.
    Func mean("mean");
    {
        RDom r_mean(0, n, "r_mean");
        Expr zero = cast<num_t>(Expr(0.0));

        mean(j) = zero;
        // Incremental average: sum of data / float_n
        mean(j) += data_param(j, r_mean) / float_n_param;
    }

    // Column-wise variance (accumulated, no division by float_n yet):
    //   var[j] = sum_i (data[i][j] - mean[j])^2
    Func var("var");
    {
        RDom r_var(0, n, "r_var");
        Expr zero = cast<num_t>(Expr(0.0));

        var(j) = zero;
        Expr diff = data_param(j, r_var) - mean(j);
        var(j) += diff * diff;
    }

    // Standard deviation with epsilon handling:
    // Original C:
    //   stddev[j] = 0;
    //   for (i) stddev[j] += (data[i][j] - mean[j])^2;
    //   stddev[j] /= float_n;
    //   stddev[j] = sqrt(stddev[j]);
    //   stddev[j] = stddev[j] <= eps ? 1.0 : stddev[j];
    //
    // We compute:
    //   sigma = sqrt(var[j] / float_n);
    //   stddev[j] = (sigma <= eps) ? 1.0 : sigma;
    Func stddev("stddev");
    {
        Expr eps = cast<num_t>(Expr(0.1));  // SCALAR_VAL(0.1)
        Expr one = cast<num_t>(Expr(1.0));
        Expr sigma = sqrt(var(j) / float_n_param);
        stddev(j) = select(sigma <= eps, one, sigma);
    }

    // Precompute a per-column scaling factor:
    //   scale[j] = 1 / (sqrt(float_n) * stddev[j])
    // so that normalization can use a single multiply instead of a divide.
    Func scale("scale");
    {
        Expr sqrt_n = sqrt(float_n_param);
        Expr one = cast<num_t>(Expr(1.0));
        scale(j) = one / (sqrt_n * stddev(j));
    }

    // Center and reduce the column vectors:
    // Original C:
    //   for (i = 0; i < N; i++)
    //     for (j = 0; j < M; j++) {
    //       data[i][j] -= mean[j];
    //       data[i][j] /= sqrt(float_n) * stddev[j];
    //     }
    //
    // We'll compute a new Func `normalized(j, i)` instead of modifying data in place:
    //   normalized(j, i) = (data[i][j] - mean[j]) * scale[j]
    Func normalized("normalized");
    {
        normalized(j, i) = (data_param(j, i) - mean(j)) * scale(j);
    }

    // Correlation matrix:
    // Original C:
    //   for (i = 0; i < M-1; i++) {
    //     corr[i][i] = 1.0;
    //     for (j = i+1; j < M; j++) {
    //       corr[i][j] = 0.0;
    //       for (k = 0; k < N; k++)
    //         corr[i][j] += data[k][i] * data[k][j];
    //       corr[j][i] = corr[i][j];
    //     }
    //   }
    //   corr[M-1][M-1] = 1.0;
    //
    // Using normalized data, the off-diagonals are dot products of
    // normalized columns. We compute the full symmetric matrix and then
    // explicitly set the diagonal to 1.0 to match the original semantics.
    Func corr_base("corr_base");
    {
        RDom r_k(0, n, "r_k");
        Expr zero = cast<num_t>(Expr(0.0));

        corr_base(q, p) = zero;
        corr_base(q, p) += normalized(q, r_k) * normalized(p, r_k);
    }

    Func corr("corr");
    {
        Expr one = cast<num_t>(Expr(1.0));
        // corr_buf(q, p) corresponds to C corr[p][q]
        corr(q, p) = select(p == q, one, corr_base(q, p));
    }

    // -----------------------
    // Scheduling / Optimization
    // -----------------------

    Target target = get_jit_target_from_environment();
    const Type elem_type = type_of<num_t>();
    const int vec_width  = natural_vector_size(elem_type, target);

    // 1) Column-wise stats: independent over j, so parallelize across columns.
    mean
        .compute_root()
        .parallel(j);

    var
        .compute_root()
        .parallel(j);

    stddev
        .compute_root()
        .parallel(j);

    scale
        .compute_root()
        .parallel(j);

    // 2) Normalization: 2D N×M; layout is normalized(j,i) so j is innermost.
    //    We tile over rows (i) for cache locality, parallelize across tiles,
    //    and vectorize across columns (j).
    Var io("io_norm"), ii("ii_norm");
    normalized
        .compute_root()
        .split(i, io, ii, 64)          // 64-row tiles; tune for cache
        .parallel(io)                  // parallelize across row-tiles
        .vectorize(j, vec_width);      // vectorize across contiguous columns

    // 3) Correlation reduction:
    //    corr_base(q,p) = sum_k normalized(q,k) * normalized(p,k)
    //
    //    We compute corr_base at root, parallelize across p (rows of corr),
    //    and vectorize across q (columns), which are contiguous in memory.
    corr_base.compute_root();

    corr_base
        .update()
        .parallel(p)                   // different rows of corr in parallel
        .vectorize(q, vec_width);      // vectorize across contiguous q

    // 4) Final corr assembly: pure pointwise assignment from corr_base with
    //    a diagonal fixup. Parallel over rows and vectorize columns.
    corr
        .compute_root()
        .parallel(p)
        .vectorize(q, vec_width);

    // Bind parameters and input buffer.
    data_param.set(data);
    float_n_param.set(float_n);

    // Build a pipeline for the final correlation Func.
    Pipeline pipeline(corr);

    // JIT compile the pipeline with the chosen target.
    pipeline.compile_jit(target);

    // Time only the kernel execution (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize corr into corr_buf.
    pipeline.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, similar to gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr_buf(jj, ii) corresponds to corr[ii][jj] in C.
                std::cerr << corr_buf(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
