                int n,
                num_t *float_n,
                Halide::Buffer<num_t, 2> data)
{
    // float_n = (DATA_TYPE) n;
    *float_n = static_cast<num_t>(n);

    // Use Halide to fill the data buffer.
    Var i("i_init"), j("j_init");
    Func init_data("init_data");

    // C code: data[i][j] = (DATA_TYPE)(i*j)/M + i;
    // Here, i and j are ints; M is 'm'.
    // We must ensure the division is done in floating point, so we cast
    // both numerator and denominator to num_t.
    Expr ij     = i * j;
    Expr num    = cast<num_t>(ij);
    Expr denom  = cast<num_t>(m);
    Expr term_i = cast<num_t>(i);

    // In Halide layout, we store as data(j, i) => width = m (j), height = n (i).
    init_data(j, i) = num / denom + term_i;

    // Simple but effective schedule for initialization:
    //  - parallel over rows (i)
    //  - vectorize over contiguous x-dimension (j)
    Target init_target = get_host_target();
    const int vecw = init_target.natural_vector_size(type_of<num_t>());
    init_data
        .compute_root()
        .parallel(i)
        .vectorize(j, vecw);

    // Realize into the provided buffer (width = m, height = n).
    init_data.realize(data);
}


int main(int argc, char *argv[]) {
    // Problem size (from correlation.hpp / defines.hpp).
    int n = N; // number of rows (samples)
    int m = M; // number of columns (variables)

    // Scalar corresponding to float_n in the original C code.
    num_t float_n = static_cast<num_t>(n);

    // Buffers:
    //  - data: N x M in C as data[i][j]
    //    => Buffer width = M (j), height = N (i) => data(j, i)
    //  - corr: M x M in C as corr[i][j]
    //    => Buffer width = M (j), height = M (i) => corr(j, i)
    Halide::Buffer<num_t, 2> data(m, n);
    Halide::Buffer<num_t, 2> corr_buf(m, m);

    // Initialize the input data (and float_n, though we also set float_n directly).
    init_array(m, n, &float_n, data);

    // --- Build Halide correlation pipeline ---

    // ImageParam for the input data.
    // Layout: data_param(j, i) corresponds to C data[i][j].
    ImageParam data_param(type_of<num_t>(), 2, "data_param");

    // Scalar parameter for float_n.
    Param<num_t> float_n_param("float_n_param");

    // Vars:
    //   i = row index in data        (0..n-1)
    //   j = column index in data     (0..m-1)
    //   p,q = indices for correlation matrix (0..m-1)
    Var i("i"), j("j"), p("p"), q("q");

    // To reduce redundant divisions, we follow the original PolyBench C
    // structure closely:
    //
    //   mean[j]  = (1/N) * sum_i data[i][j]
    //   var[j]   = sum_i (data[i][j] - mean[j])^2
    //   stddev[j]= sqrt(var[j]/N), then eps-clamped
    //   data[i][j] <- (data[i][j] - mean[j]) / (sqrt(N)*stddev[j])
    //   corr[i][j]= sum_k data[k][i] * data[k][j]
    //
    // We express these as Halide Funcs with an emphasis on data locality
    // and minimizing expensive ops (division, sqrt) inside large loops.

    // ------------------------------------------------------------------
    // Column-wise sums and means.
    // ------------------------------------------------------------------

    // mean_sum[j] = sum_i data[i][j]
    Func mean_sum("mean_sum");
    {
        RDom r_mean(0, n, "r_mean");
        Expr zero = cast<num_t>(0);

        mean_sum(j) = zero;
        mean_sum(j) += data_param(j, r_mean);
    }

    // mean[j] = mean_sum[j] / float_n
    Func mean("mean");
    {
        // Compute reciprocal once symbolically; Halide will hoist this.
        Expr inv_float_n = cast<num_t>(1) / float_n_param;
        mean(j) = mean_sum(j) * inv_float_n;
    }

    // ------------------------------------------------------------------
    // Column-wise variance (sum of squared deviations).
    // ------------------------------------------------------------------
    // var[j] = sum_i (data[i][j] - mean[j])^2
    Func var("var");
    {
        RDom r_var(0, n, "r_var");
        Expr zero = cast<num_t>(0);

        var(j) = zero;
        Expr diff = data_param(j, r_var) - mean(j);
        var(j) += diff * diff;
    }

    // ------------------------------------------------------------------
    // Standard deviation with epsilon handling.
    // ------------------------------------------------------------------
    // stddev[j] = sqrt(var[j] / float_n);
    // if stddev[j] <= eps then stddev[j] = 1.0;
    Func stddev("stddev");
    {
        Expr inv_float_n = cast<num_t>(1) / float_n_param;
        Expr eps = cast<num_t>(1) / cast<num_t>(10);  // 0.1 without float literal ambiguity
        Expr one = cast<num_t>(1);

        Expr sigma = sqrt(var(j) * inv_float_n);
        stddev(j) = select(sigma <= eps, one, sigma);
    }

    // ------------------------------------------------------------------
    // Normalization factor and normalized data.
    // ------------------------------------------------------------------
    // Precompute 1 / (sqrt(float_n) * stddev[j]) to avoid a division
    // inside the large N*M loop.
    Func norm_factor("norm_factor");
    {
        Expr sqrt_n = sqrt(float_n_param);
        Expr one = cast<num_t>(1);
        norm_factor(j) = one / (sqrt_n * stddev(j));
    }

    // normalized(j, i) = (data[i][j] - mean[j]) * norm_factor[j]
    // This corresponds to the in-place normalization in the original C
    // code but keeps the original data intact.
    Func normalized("normalized");
    {
        normalized(j, i) = (data_param(j, i) - mean(j)) * norm_factor(j);
    }

    // ------------------------------------------------------------------
    // Correlation matrix (full symmetric), then force diagonal to 1.
    // ------------------------------------------------------------------
    // corr_base(q, p) = sum_k normalized[k, q] * normalized[k, p]
    Func corr_base("corr_base");
    {
        RDom r_k(0, n, "r_k");
        Expr zero = cast<num_t>(0);

        corr_base(q, p) = zero;
        corr_base(q, p) += normalized(q, r_k) * normalized(p, r_k);
    }

    // Final correlation, with explicit diagonal = 1.0 to match original.
    Func corr("corr");
    {
        Expr one = cast<num_t>(1);
        // corr_buf(q, p) corresponds to C corr[p][q]
        corr(q, p) = select(p == q, one, corr_base(q, p));
    }

    // ------------------------------------------------------------------
    // Scheduling for performance
    // ------------------------------------------------------------------
    // Use a reasonable vector width for the current target.
    Target target = get_jit_target_from_environment();
    const int vecw = target.natural_vector_size(type_of<num_t>());

    // mean_sum: 1D reduction over i, independent over j.
    //   - parallelize across columns (j)
    //   - vectorize across contiguous j
    mean_sum.compute_root();
    mean_sum.update()
        .parallel(j)
        .vectorize(j, vecw);

    // mean: simple pointwise transform of mean_sum.
    mean
        .compute_root()
        .parallel(j)
        .vectorize(j, vecw);

    // var: 1D reduction over i, independent across j; reuse same pattern.
    var.compute_root();
    var.update()
        .parallel(j)
        .vectorize(j, vecw);

    // stddev and norm_factor: 1D maps, cheap, parallel across j.
    stddev
        .compute_root()
        .parallel(j)
        .vectorize(j, vecw);

    norm_factor
        .compute_root()
        .parallel(j)
        .vectorize(j, vecw);

    // normalized: 2D N x M array.
    //   - parallelize across rows (i) to use many cores
    //   - vectorize across contiguous columns (j)
    normalized
        .compute_root()
        .parallel(i)
        .vectorize(j, vecw);

    // corr_base: 2D M x M reduction over k (rows of normalized).
    // We:
    //   - compute at root so we can schedule independently
    //   - parallelize across the p dimension (rows of correlation)
    //   - vectorize across q (contiguous x dimension)
    corr_base.compute_root();
    corr_base.update()
        .parallel(p)
        .vectorize(q, vecw);

    // corr: final symmetric matrix; pure, so we simply map across p and q.
    corr
        .compute_root()
        .parallel(p)
        .vectorize(q, vecw);

    // Bind parameters and input buffer.
    data_param.set(data);
    float_n_param.set(float_n);

    // Build a pipeline for the final correlation Func.
    Pipeline pipeline(corr);

    // JIT compile the pipeline for the chosen target.
    pipeline.compile_jit(target);

    // Time only the kernel execution (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize corr into corr_buf.
    pipeline.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, similar to gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr_buf(jj, ii) corresponds to corr[ii][jj] in C.
                std::cerr << corr_buf(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
