    //   corr[M-1][M-1] = 1.0;
    //
    // Using normalized data, off-diagonals are:
    //   corr_base[p][q] = sum_k normalized[k][p] * normalized[k][q]
    //
    // We compute the full symmetric matrix and then set the diagonal
    // to 1.0 via a select(), matching original semantics.
    // -------------------------------------------------------------------------
    Func corr_base("corr_base");
    {
        RDom r_k(0, n, "r_k");
        corr_base(q, p) = zero_f;
        corr_base(q, p) += normalized(q, r_k) * normalized(p, r_k);
    }

    Func corr("corr");
    {
        corr(q, p) = select(p == q, one_f, corr_base(q, p));
    }

    // -------------------------------------------------------------------------
    // Scheduling
    //
    // Goal: improve data locality and exploit parallelism/vectorization
    //       on a modern x64 CPU while keeping the algorithm unchanged.
    // -------------------------------------------------------------------------

    // 1D reductions: mean_sum and var_sum
    // Parallelize across columns (j) and vectorize along j.
    mean_sum.compute_root();
    mean_sum
        .update()
        .parallel(j)
        .vectorize(j, vec_width);

    mean.compute_root()
        .parallel(j)
        .vectorize(j, vec_width);

    var_sum.compute_root();
    var_sum
        .update()
        .parallel(j)
        .vectorize(j, vec_width);

    stddev.compute_root()
        .parallel(j)
        .vectorize(j, vec_width);

    inv_scale.compute_root()
        .parallel(j)
        .vectorize(j, vec_width);

    // 2D normalized data:
    // Rows (i) are independent; we parallelize across rows,
    // and vectorize across columns (j) which are contiguous in memory.
    normalized.compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Correlation accumulation:
    //
    // We tile the (p, q) space so that each tile of the correlation
    // matrix is computed by a separate worker thread, and within each
    // tile we vectorize across the innermost dimension. This improves
    // cache locality when reusing normalized columns.
    Var p_outer("p_outer"), p_inner("p_inner");
    Var q_outer("q_outer"), q_inner("q_inner");
    Var tile_index("tile_index");

    const int tile_p = 32;
    const int tile_q = 32;

    corr_base.compute_root();
    corr_base
        .tile(p, q, p_outer, q_outer, p_inner, q_inner, tile_p, tile_q)
        .fuse(p_outer, q_outer, tile_index)
        .parallel(tile_index)
        .vectorize(q_inner, vec_width);

    // The final corr() is a simple elementwise transformation of corr_base:
    // just set the diagonal to 1.0; it's cheap, so a simple root schedule
    // with vectorization is sufficient.
    corr.compute_root()
        .parallel(p)
        .vectorize(q, vec_width);

    // Bind parameters and input buffer.
    data_param.set(data);
    float_n_param.set(float_n);

    // Build a pipeline for the final correlation Func.
    Pipeline pipeline(corr);

    // JIT compile the pipeline for the chosen target.
    pipeline.compile_jit(target);

    // Time only the kernel execution (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize corr into corr_buf.
    pipeline.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, similar to gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr_buf(jj, ii) corresponds to corr[ii][jj] in C.
                std::cerr << corr_buf(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

